script:
document.addEventListener('DOMContentLoaded', function() {
  const leftBtn = document.getElementById('left-btn');
  const rightBtn = document.getElementById('right-btn');
  const bothBtn = document.getElementById('both-btn');
  const alternateBtn = document.getElementById('alternate-btn');
  const stopBtn = document.getElementById('stop-btn');
  const leftEar = document.getElementById('left-ear');
  const rightEar = document.getElementById('right-ear');
  const freqSelect = document.getElementById('freq-select');
  const volume = document.getElementById('volume');
  const volDisplay = document.getElementById('vol-display');
  const bassCard = document.getElementById('bass-card');
  const trebleCard = document.getElementById('treble-card');
  const fullrangeCard = document.getElementById('fullrange-card');

  let audioContext = null;
  let oscillator = null;
  let gainNode = null;
  let panNode = null;
  let alternateInterval = null;

  function playTone(pan) {
    stopTone();
    if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();

    oscillator = audioContext.createOscillator();
    gainNode = audioContext.createGain();
    panNode = audioContext.createStereoPanner();

    oscillator.frequency.setValueAtTime(parseInt(freqSelect.value), audioContext.currentTime);
    gainNode.gain.setValueAtTime(volume.value / 100 * 0.5, audioContext.currentTime);
    panNode.pan.setValueAtTime(pan, audioContext.currentTime);

    oscillator.connect(gainNode);
    gainNode.connect(panNode);
    panNode.connect(audioContext.destination);
    oscillator.start();

    stopBtn.disabled = false;
    updateIndicators(pan);
  }

  function stopTone() {
    if (oscillator) { oscillator.stop(); oscillator.disconnect(); oscillator = null; }
    if (alternateInterval) { clearInterval(alternateInterval); alternateInterval = null; }
    stopBtn.disabled = true;
    leftEar.classList.remove('active');
    rightEar.classList.remove('active');
  }

  function updateIndicators(pan) {
    leftEar.classList.toggle('active', pan <= 0);
    rightEar.classList.toggle('active', pan >= 0);
  }

  function playSweep(start, end, duration) {
    stopTone();
    if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();
    oscillator = audioContext.createOscillator();
    gainNode = audioContext.createGain();
    oscillator.frequency.setValueAtTime(start, audioContext.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(end, audioContext.currentTime + duration);
    gainNode.gain.setValueAtTime(volume.value / 100 * 0.3, audioContext.currentTime);
    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);
    oscillator.start();
    oscillator.stop(audioContext.currentTime + duration);
    stopBtn.disabled = false;
    leftEar.classList.add('active');
    rightEar.classList.add('active');
    setTimeout(stopTone, duration * 1000);
  }

  leftBtn.addEventListener('click', () => playTone(-1));
  rightBtn.addEventListener('click', () => playTone(1));
  bothBtn.addEventListener('click', () => playTone(0));
  stopBtn.addEventListener('click', stopTone);

  alternateBtn.addEventListener('click', () => {
    let isLeft = true;
    playTone(-1);
    alternateInterval = setInterval(() => {
      isLeft = !isLeft;
      if (panNode) panNode.pan.setValueAtTime(isLeft ? -1 : 1, audioContext.currentTime);
      updateIndicators(isLeft ? -1 : 1);
    }, 500);
  });

  volume.addEventListener('input', () => {
    volDisplay.textContent = volume.value + '%';
    if (gainNode) gainNode.gain.setValueAtTime(volume.value / 100 * 0.5, audioContext.currentTime);
  });

  bassCard.addEventListener('click', () => playSweep(20, 200, 3));
  trebleCard.addEventListener('click', () => playSweep(2000, 16000, 3));
  fullrangeCard.addEventListener('click', () => playSweep(20, 20000, 5));

  [bassCard, trebleCard, fullrangeCard].forEach(function(card) {
    card.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); card.click(); }
    });
  });
});

