.ear-indicator{width:64px;height:64px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.3rem;font-weight:700;font-family:'JetBrains Mono',ui-monospace,monospace;background:var(--panel-2);color:var(--ink-2);border:1px solid var(--border);transition:all .2s;}
.ear-indicator.active{background:var(--amber);color:var(--bg);border-color:var(--amber);animation:pulse-scale .5s infinite;box-shadow:0 0 0 4px var(--amber-dim);}
@keyframes pulse-scale{0%,100%{transform:scale(1);}50%{transform:scale(1.08);}}
.headphone-icon{font-size:4.5rem;color:var(--ink-3);}
.quick-test-card{cursor:pointer;transition:transform .15s,border-color .15s;}
.quick-test-card:hover{transform:translateY(-3px);border-color:var(--amber);}
.quick-test-card:focus-visible{outline:2px solid var(--amber);outline-offset:2px;}

input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:4px;border-radius:99px;background:var(--border);outline:none;margin:.5rem 0;}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:16px;height:16px;border-radius:50%;background:var(--amber);cursor:pointer;border:2px solid var(--panel-2);box-shadow:0 0 0 1px var(--border);}
input[type=range]::-moz-range-track{height:4px;border-radius:99px;background:var(--border);}
input[type=range]::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:var(--amber);cursor:pointer;border:2px solid var(--panel-2);box-shadow:0 0 0 1px var(--border);}
